  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = this->market(symbol);
                        ccxt::any request = ccxt::dict{
                            {std::string("primaryCurrencyCode"),
                             ::getValue(market, std::string("baseId"))},
                            {std::string("secondaryCurrencyCode"),
                             ::getValue(market, std::string("quoteId"))},
                        };
                        ccxt::any response =
                            awaitValue(this->publicGetGetOrderBook(
                                this->extend(request, params)));
                        ccxt::any timestamp = this->parse8601(this->safeString(
                            response, std::string("CreatedTimestampUtc")));
                        return this->parseOrderBook(
                            response, ::getValue(market, std::string("symbol")),
                            timestamp, std::string("BuyOrders"),
                            std::string("SellOrders"), std::string("Price"),
                            std::string("Volume"));
                      })
        .share();
  }

  ccxt::any parseTicker(ccxt::any ticker,
                        ccxt::any market = ccxt::any{}) override {
    // {
    //     "DayHighestPrice":43489.49,
    //     "DayLowestPrice":41998.32,
    //     "DayAvgPrice":42743.9,
    //     "DayVolumeXbt":44.54515625000,
    //     "DayVolumeXbtInSecondaryCurrrency":0.12209818,
    //     "CurrentLowestOfferPrice":43619.64,
    //     "CurrentHighestBidPrice":43153.58,
    //     "LastPrice":43378.43,
    //     "PrimaryCurrencyCode":"Xbt",
    //     "SecondaryCurrencyCode":"Usd",
    //     "CreatedTimestampUtc":"2022-01-14T22:52:29.5029223Z"
    // }
    ccxt::any timestamp = this->parse8601(
        this->safeString(ticker, std::string("CreatedTimestampUtc")));
    ccxt::any baseId =
        this->safeString(ticker, std::string("PrimaryCurrencyCode"));
    ccxt::any quoteId =
        this->safeString(ticker, std::string("SecondaryCurrencyCode"));
    ccxt::any defaultMarketId = ccxt::any{};
    if (isTrue(isTrue((!isEqual(baseId, ccxt::any{}))) &&
               isTrue((!isEqual(quoteId, ccxt::any{}))))) {
      defaultMarketId = add(add(baseId, std::string("/")), quoteId);
    }
    market = this->safeMarket(defaultMarketId, market, std::string("/"));
    ccxt::any symbol = ::getValue(market, std::string("symbol"));
    ccxt::any last = this->safeString(ticker, std::string("LastPrice"));
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("high"),
             this->safeString(ticker, std::string("DayHighestPrice"))},
            {std::string("low"),
             this->safeString(ticker, std::string("DayLowestPrice"))},
            {std::string("bid"),
             this->safeString(ticker, std::string("CurrentHighestBidPrice"))},
            {std::string("bidVolume"), ccxt::any{}},
            {std::string("ask"),
             this->safeString(ticker, std::string("CurrentLowestOfferPrice"))},
            {std::string("askVolume"), ccxt::any{}},
            {std::string("vwap"), ccxt::any{}},
            {std::string("open"), ccxt::any{}},
            {std::string("close"), last},
            {std::string("last"), last},
            {std::string("previousClose"), ccxt::any{}},
            {std::string("change"), ccxt::any{}},
            {std::string("percentage"), ccxt::any{}},
            {std::string("average"),
             this->safeString(ticker, std::string("DayAvgPrice"))},
            {std::string("baseVolume"),
             this->safeString(ticker,
                              std::string("DayVolumeXbtInSecondaryCurrrency"))},
            {std::string("quoteVolume"), ccxt::any{}},
            {std::string("info"), ticker},
        },
        market);
  }

