  ccxt::any parseOrder(ccxt::any order,
                       ccxt::any market = ccxt::any{}) override {
    //
    // fetchOrder
    //
    //     {
    //         "OrderGuid": "c7347e4c-b865-4c94-8f74-d934d4b0b177",
    //         "CreatedTimestampUtc": "2014-09-23T12:39:34.3817763Z",
    //         "Type": "MarketBid",
    //         "VolumeOrdered": 5.0,
    //         "VolumeFilled": 5.0,
    //         "Price": null,
    //         "AvgPrice": 100.0,
    //         "ReservedAmount": 0.0,
    //         "Status": "Filled",
    //         "PrimaryCurrencyCode": "Xbt",
    //         "SecondaryCurrencyCode": "Usd"
    //     }
    //
    // fetchOpenOrders & fetchClosedOrders
    //
    //     {
    //         "OrderGuid": "b8f7ad89-e4e4-4dfe-9ea3-514d38b5edb3",
    //         "CreatedTimestampUtc": "2020-09-08T03:04:18.616367Z",
    //         "OrderType": "LimitOffer",
    //         "Volume": 0.0005,
    //         "Outstanding": 0.0005,
    //         "Price": 113885.83,
    //         "AvgPrice": 113885.83,
    //         "Value": 56.94,
    //         "Status": "Open",
    //         "PrimaryCurrencyCode": "Xbt",
    //         "SecondaryCurrencyCode": "Usd",
    //         "FeePercent": 0.005,
    //     }
    //
    // cancelOrder
    //
    //    {
    //        "AvgPrice": 455.48,
    //        "CreatedTimestampUtc": "2022-08-05T06:42:11.3032208Z",
    //        "OrderGuid": "719c495c-a39e-4884-93ac-280b37245037",
    //        "Price": 485.76,
    //        "PrimaryCurrencyCode": "Xbt",
    //        "ReservedAmount": 0.358,
    //        "SecondaryCurrencyCode": "Usd",
    //        "Status": "Cancelled",
    //        "Type": "LimitOffer",
    //        "VolumeFilled": 0,
    //        "VolumeOrdered": 0.358
    //    }
    ccxt::any symbol = ccxt::any{};
    ccxt::any baseId =
        this->safeString(order, std::string("PrimaryCurrencyCode"));
    ccxt::any quoteId =
        this->safeString(order, std::string("SecondaryCurrencyCode"));
    ccxt::any base = ccxt::any{};
    ccxt::any quote = ccxt::any{};
    if (isTrue(isTrue((!isEqual(baseId, ccxt::any{}))) &&
               isTrue((!isEqual(quoteId, ccxt::any{}))))) {
      base = this->safeCurrencyCode(baseId);
      quote = this->safeCurrencyCode(quoteId);
      symbol = add(add(base, std::string("/")), quote);
    } else if (isTrue(!isEqual(market, ccxt::any{}))) {
      symbol = ::getValue(market, std::string("symbol"));
      base = ::getValue(market, std::string("base"));
      quote = ::getValue(market, std::string("quote"));
    }
    ccxt::any orderType =
        this->safeString2(order, std::string("Type"), std::string("OrderType"));
    ccxt::any side = ccxt::any{};
    if (isTrue(!isEqual(orderType, ccxt::any{}))) {
      if (isTrue(isGreaterThanOrEqual(getIndexOf(orderType, std::string("Bid")),
                                      0))) {
        side = std::string("buy");
      } else if (isTrue(isGreaterThanOrEqual(
                     getIndexOf(orderType, std::string("Offer")), 0))) {
        side = std::string("sell");
      }
      if (isTrue(isGreaterThanOrEqual(
              getIndexOf(orderType, std::string("Market")), 0))) {
        orderType = std::string("market");
      } else if (isTrue(isGreaterThanOrEqual(
                     getIndexOf(orderType, std::string("Limit")), 0))) {
        orderType = std::string("limit");
      }
    }
    ccxt::any timestamp = this->parse8601(
        this->safeString(order, std::string("CreatedTimestampUtc")));
    ccxt::any filled = this->safeString(order, std::string("VolumeFilled"));
    ccxt::any feeRate = this->safeString(order, std::string("FeePercent"));
    ccxt::any feeCost = ccxt::any{};
    if (isTrue(isTrue(!isEqual(feeRate, ccxt::any{})) &&
               isTrue(!isEqual(filled, ccxt::any{})))) {
      feeCost = ccxt::Precise::stringMul(feeRate, filled);
    }
    return this->safeOrder(
        ccxt::dict{
            {std::string("info"), order},
            {std::string("id"),
             this->safeString(order, std::string("OrderGuid"))},
            {std::string("clientOrderId"), ccxt::any{}},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("lastTradeTimestamp"), ccxt::any{}},
            {std::string("symbol"), symbol},
            {std::string("type"), orderType},
            {std::string("timeInForce"),
             this->parseTimeInForce(
                 this->safeString(order, std::string("TimeInForce")))},
            {std::string("postOnly"), ccxt::any{}},
            {std::string("side"), side},
            {std::string("price"),
             this->safeString(order, std::string("Price"))},
            {std::string("triggerPrice"), ccxt::any{}},
            {std::string("cost"),
             this->safeString(order, std::string("Value"))},
            {std::string("average"),
             this->safeString(order, std::string("AvgPrice"))},
            {std::string("amount"),
             this->safeString2(order, std::string("VolumeOrdered"),
                               std::string("Volume"))},
            {std::string("filled"), filled},
            {std::string("remaining"),
             this->safeString(order, std::string("Outstanding"))},
            {std::string("status"), this->parseOrderStatus(this->safeString(
                                        order, std::string("Status")))},
            {std::string("fee"),
             ccxt::dict{
                 {std::string("rate"), feeRate},
                 {std::string("cost"), feeCost},
                 {std::string("currency"), base},
             }},
            {std::string("trades"), ccxt::any{}},
        },
        market);
  }

  virtual ccxt::any parseOrderStatus(ccxt::any status) {
    ccxt::any statuses = ccxt::dict{
        {std::string("Open"), std::string("open")},
        {std::string("PartiallyFilled"), std::string("open")},
        {std::string("Filled"), std::string("closed")},
        {std::string("PartiallyFilledAndCancelled"), std::string("canceled")},
        {std::string("Cancelled"), std::string("canceled")},
        {std::string("PartiallyFilledAndExpired"), std::string("canceled")},
        {std::string("Expired"), std::string("canceled")},
        {std::string("Failed"), std::string("canceled")},
    };
    return this->safeString(statuses, status, status);
  }

  virtual ccxt::any parseTimeInForce(ccxt::any timeInForce) {
    ccxt::any timeInForces = ccxt::dict{
        {std::string("Gtc"), std::string("GTC")},
        {std::string("Moc"), std::string("PO")},
        {std::string("Fok"), std::string("FOK")},
        {std::string("Ioc"), std::string("IOC")},
    };
    return this->safeString(timeInForces, timeInForce, timeInForce);
  }

  /**
   * @method
   * @name independentreserve#fetchOrder
   * @description fetches information on an order made by the user
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any response = awaitValue(
                            this->privatePostGetOrderDetails(this->extend(
                                ccxt::dict{
                                    {std::string("orderGuid"), id},
                                },
                                params)));
                        ccxt::any market = ccxt::any{};
                        if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                          market = this->market(symbol);
                        }
                        return this->parseOrder(response, market);
                      })
        .share();
  }

  /**
   * @method
   * @name independentreserve#fetchOpenOrders
   * @description fetch all unfilled currently open orders
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch open orders for
   * @param {int} [limit] the maximum number of  open orders structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOpenOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                  ccxt::any limit = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("primaryCurrencyCode"),
                              ::getValue(market, std::string("baseId")));
                   ::setValue(request, std::string("secondaryCurrencyCode"),
                              ::getValue(market, std::string("quoteId")));
                 }
                 if (isTrue(isEqual(limit, ccxt::any{}))) {
                   limit = 50;
                 }
                 ::setValue(request, std::string("pageIndex"), 1);
                 ::setValue(request, std::string("pageSize"), limit);
                 ccxt::any response = awaitValue(this->privatePostGetOpenOrders(
                     this->extend(request, params)));
                 ccxt::any data = this->safeList(response, std::string("Data"),
                                                 ccxt::list{});
                 return this->parseOrders(data, market, since, limit);
               })
        .share();
  }

