  ccxt::any parseTrade(ccxt::any trade,
                       ccxt::any market = ccxt::any{}) override {
    ccxt::any timestamp =
        this->parse8601(::getValue(trade, std::string("TradeTimestampUtc")));
    ccxt::any id = this->safeString(trade, std::string("TradeGuid"));
    ccxt::any orderId = this->safeString(trade, std::string("OrderGuid"));
    ccxt::any priceString =
        this->safeString2(trade, std::string("Price"),
                          std::string("SecondaryCurrencyTradePrice"));
    ccxt::any amountString =
        this->safeString2(trade, std::string("VolumeTraded"),
                          std::string("PrimaryCurrencyAmount"));
    ccxt::any price = this->parseNumber(priceString);
    ccxt::any amount = this->parseNumber(amountString);
    ccxt::any cost =
        this->parseNumber(ccxt::Precise::stringMul(priceString, amountString));
    ccxt::any baseId =
        this->safeString(trade, std::string("PrimaryCurrencyCode"));
    ccxt::any quoteId =
        this->safeString(trade, std::string("SecondaryCurrencyCode"));
    ccxt::any marketId = ccxt::any{};
    if (isTrue(isTrue((!isEqual(baseId, ccxt::any{}))) &&
               isTrue((!isEqual(quoteId, ccxt::any{}))))) {
      marketId = add(add(baseId, std::string("/")), quoteId);
    }
    ccxt::any symbol = this->safeSymbol(marketId, market, std::string("/"));
    ccxt::any side = this->safeString(trade, std::string("OrderType"));
    if (isTrue(!isEqual(side, ccxt::any{}))) {
      if (isTrue(
              isGreaterThanOrEqual(getIndexOf(side, std::string("Bid")), 0))) {
        side = std::string("buy");
      } else if (isTrue(isGreaterThanOrEqual(
                     getIndexOf(side, std::string("Offer")), 0))) {
        side = std::string("sell");
      }
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("info"), trade},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), symbol},
            {std::string("order"), orderId},
            {std::string("type"), ccxt::any{}},
            {std::string("side"), side},
            {std::string("takerOrMaker"), ccxt::any{}},
            {std::string("price"), price},
            {std::string("amount"), amount},
            {std::string("cost"), cost},
            {std::string("fee"), ccxt::any{}},
        },
        market);
  }

