  ccxt::any parseDepositAddress(ccxt::any depositAddress,
                                ccxt::any currency = ccxt::any{}) override {
    //
    //    {
    //        Tag: '3307446684',
    //        DepositAddress:
    //        'GCCQH4HACMRAD56EZZZ4TOIDQQRVNADMJ35QOFWF4B2VQGODMA2WVQ22',
    //        LastCheckedTimestampUtc: '2024-02-20T11:13:35.6912985Z',
    //        NextUpdateTimestampUtc: '2024-02-20T11:14:56.5112394Z'
    //    }
    //
    ccxt::any address =
        this->safeString(depositAddress, std::string("DepositAddress"));
    this->checkAddress(address);
    return ccxt::dict{
        {std::string("info"), depositAddress},
        {std::string("currency"),
         this->safeString(currency, std::string("code"))},
        {std::string("network"), ccxt::any{}},
        {std::string("address"), address},
        {std::string("tag"),
         this->safeString(depositAddress, std::string("Tag"))},
    };
  }

  /**
   * @method
   * @name independentreserve#withdraw
   * @description make a withdrawal
   * @see
   * https://www.independentreserve.com/features/api#WithdrawDigitalCurrency
   * @param {string} code unified currency code
   * @param {float} amount the amount to withdraw
   * @param {string} address the address to withdraw to
   * @param {string} tag
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   *
   * EXCHANGE SPECIFIC PARAMETERS
   * @param {object} [params.comment] withdrawal comment, should not exceed 500
   * characters
   * @returns {object} a [transaction structure]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<ccxt::any>
  withdraw(ccxt::any code, ccxt::any amount, ccxt::any address,
           ccxt::any tag = ccxt::any{},
           ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any tagparamsVariable =
                     this->handleWithdrawTagAndParams(tag, params);
                 tag = ::getValue(tagparamsVariable, 0);
                 params = ::getValue(tagparamsVariable, 1);
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any currency = this->currency(code);
                 ccxt::any request = ccxt::dict{
                     {std::string("primaryCurrencyCode"),
                      ::getValue(currency, std::string("id"))},
                     {std::string("withdrawalAddress"), address},
                     {std::string("amount"),
                      this->currencyToPrecision(code, amount)},
                 };
                 if (isTrue(!isEqual(tag, ccxt::any{}))) {
                   ::setValue(request, std::string("destinationTag"), tag);
                 }
                 ccxt::any networkCode = ccxt::any{};
                 ccxt::any networkCodeparamsVariable =
                     this->handleNetworkCodeAndParams(params);
                 networkCode = ::getValue(networkCodeparamsVariable, 0);
                 params = ::getValue(networkCodeparamsVariable, 1);
                 if (isTrue(!isEqual(networkCode, ccxt::any{}))) {
                   throw BadRequest(toString(
                       add(this->id, std::string(" withdraw () does not accept "
                                                 "params[\"networkCode\"]"))));
                 }
                 ccxt::any response =
                     awaitValue(this->privatePostWithdrawDigitalCurrency(
                         this->extend(request, params)));
                 //
                 //    {
                 //        "TransactionGuid":
                 //        "dc932e19-562b-4c50-821e-a73fd048b93b",
                 //        "PrimaryCurrencyCode": "Bch",
                 //        "CreatedTimestampUtc":
                 //        "2020-04-01T05:26:30.5093622+00:00", "Amount": {
                 //            "Total": 0.1231,
                 //            "Fee": 0.0001
                 //        },
                 //        "Destination": {
                 //            "Address":
                 //            "bc1qhpqxkjpvgkckw530yfmxyr53c94q8f4273a7ez",
                 //            "Tag": null
                 //        },
                 //        "Status": "Pending",
                 //        "Transaction": null
                 //    }
                 //
                 return this->parseTransaction(response, currency);
               })
        .share();
  }

  ccxt::any parseTransaction(ccxt::any transaction,
                             ccxt::any currency = ccxt::any{},
                             ccxt::any p2 = ccxt::any{},
                             ccxt::any p3 = ccxt::any{}) override {
    //
    //    {
    //        "TransactionGuid": "dc932e19-562b-4c50-821e-a73fd048b93b",
    //        "PrimaryCurrencyCode": "Bch",
    //        "CreatedTimestampUtc": "2020-04-01T05:26:30.5093622+00:00",
    //        "Amount": {
    //            "Total": 0.1231,
    //            "Fee": 0.0001
    //        },
    //        "Destination": {
    //            "Address": "bc1qhpqxkjpvgkckw530yfmxyr53c94q8f4273a7ez",
    //            "Tag": null
    //        },
    //        "Status": "Pending",
    //        "Transaction": null
    //    }
    //
    ccxt::any amount = this->safeDict(transaction, std::string("Amount"));
    ccxt::any destination =
        this->safeDict(transaction, std::string("Destination"));
    ccxt::any currencyId =
        this->safeString(transaction, std::string("PrimaryCurrencyCode"));
    ccxt::any datetime =
        this->safeString(transaction, std::string("CreatedTimestampUtc"));
    ccxt::any address = this->safeString(destination, std::string("Address"));
    ccxt::any tag = this->safeString(destination, std::string("Tag"));
    ccxt::any code = this->safeCurrencyCode(currencyId, currency);
    return ccxt::dict{
        {std::string("info"), transaction},
        {std::string("id"),
         this->safeString(transaction, std::string("TransactionGuid"))},
        {std::string("txid"), ccxt::any{}},
        {std::string("type"), std::string("withdraw")},
        {std::string("currency"), code},
        {std::string("network"), ccxt::any{}},
        {std::string("amount"), this->safeNumber(amount, std::string("Total"))},
        {std::string("status"),
         this->safeString(transaction, std::string("Status"))},
        {std::string("timestamp"), this->parse8601(datetime)},
        {std::string("datetime"), datetime},
        {std::string("address"), address},
        {std::string("addressFrom"), ccxt::any{}},
        {std::string("addressTo"), address},
        {std::string("tag"), tag},
        {std::string("tagFrom"), ccxt::any{}},
        {std::string("tagTo"), tag},
        {std::string("updated"), ccxt::any{}},
        {std::string("comment"), ccxt::any{}},
        {std::string("fee"),
         ccxt::dict{
             {std::string("currency"), code},
             {std::string("cost"),
              this->safeNumber(amount, std::string("Fee"))},
             {std::string("rate"), ccxt::any{}},
         }},
        {std::string("internal"), false},
    };
  }

  ccxt::any sign(ccxt::any path, ccxt::any api = std::string("public"),
                 ccxt::any method = std::string("GET"),
                 ccxt::any params = ccxt::dict{},
                 ccxt::any headers = ccxt::any{},
                 ccxt::any body = ccxt::any{}) override {
    ccxt::any url =
        add(add(::getValue(::getValue(this->urls, std::string("api")), api),
                std::string("/")),
            path);
    if (isTrue(isEqual(api, std::string("public")))) {
      if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(params)), 0))) {
        url = add(url, add(std::string("?"), this->urlencode(params)));
      }
    } else {
      this->checkRequiredCredentials();
      ccxt::any nonce = this->nonce();
      ccxt::any auth =
          ccxt::list{url, add(std::string("apiKey="), this->apiKey),
                     add(std::string("nonce="), toString(nonce))};
      ccxt::any keys = getObjectKeys(params);
      for (ccxt::any i = 0; isLessThan(i, getArrayLength(keys));
           postFixIncrement(i)) {
        ccxt::any key = ::getValue(keys, i);
        ccxt::any value = toString(::getValue(params, key));
        arrayPush(auth, add(add(key, std::string("=")), value));
      }
      ccxt::any message = join(auth, std::string(","));
      ccxt::any signature =
          this->hmac(this->encode(message), this->encode(this->secret), sha256);
      ccxt::any query = ccxt::dict{};
      ::setValue(query, std::string("apiKey"), this->apiKey);
      ::setValue(query, std::string("nonce"), nonce);
      ::setValue(query, std::string("signature"), toUpperCase(signature));
      for (ccxt::any i = 0; isLessThan(i, getArrayLength(keys));
           postFixIncrement(i)) {
        ccxt::any key = ::getValue(keys, i);
        ::setValue(query, key, ::getValue(params, key));
      }
      body = this->json(query);
      headers = ccxt::dict{
          {std::string("Content-Type"), std::string("application/json")},
      };
    }
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), body},
        {std::string("headers"), headers},
    };
  }
